/** Gabarit correspondant au type de station (UNDERPASS, WADI, LOW_ROAD, FORD, OTHER). */
inline const char *tdTemplateFor(const char *type) {
  if (strcmp(type, "UNDERPASS") == 0) return TD_TEMPLATE_UNDERPASS;
  if (strcmp(type, "WADI") == 0) return TD_TEMPLATE_WADI;
  if (strcmp(type, "LOW_ROAD") == 0) return TD_TEMPLATE_LOW_ROAD;
  if (strcmp(type, "FORD") == 0) return TD_TEMPLATE_FORD;
  return TD_TEMPLATE_OTHER;
}
